def build_agent(sandbox):
    start_x = 4.5
    start_y = 1.5

    # Main beam (base of the climber) within build zone
    main_beam = sandbox.add_beam(
        x=start_x, y=start_y, width=1.0, height=3.0, density=8.0
    )

    # Lower pad on the right side of main beam
    lower_pad = sandbox.add_pad(x=5.0, y=start_y, radius=0.12, density=1.0)

    # Upper beam connected via pivot joint
    upper_beam = sandbox.add_beam(
        x=start_x, y=start_y + 3.0, width=1.0, height=3.0, density=8.0
    )

    # Upper pad on the right side of upper beam
    upper_pad = sandbox.add_pad(x=5.0, y=start_y + 3.0, radius=0.12, density=1.0)

    # Pivot joint between main beam and upper beam
    joint = sandbox.add_joint(
        main_beam, upper_beam, (start_x, start_y + 1.5), type='pivot'
    )

    # Control parameters
    control = {
        'p_torso': [lower_pad],       # Lower pad
        'p_arm': [upper_pad],         # Upper pad
        'joint': joint,               # Joint to apply motor torque
        'speed': 5.0,                 # Increased motor speed for better climbing
        'torque': 100.0               # Max torque
    }

    return {'main_body': main_beam, 'control': control}

def agent_action(sandbox, agent_body, step_count):
    main_body = agent_body['main_body']
    control = agent_body.get('control', {})
    if not control:
        return

    # Determine which pad to activate based on position
    if main_body.position.y < 2.5:
        # Activate lower pad, deactivate upper
        for p in control['p_torso']:
            sandbox.set_pad_active(p, True)
        for p in control['p_arm']:
            sandbox.set_pad_active(p, False)
    else:
        # Activate upper pad, deactivate lower
        for p in control['p_arm']:
            sandbox.set_pad_active(p, True)
        for p in control['p_torso']:
            sandbox.set_pad_active(p, False)

    # Apply motor torque to rotate upwards
    sandbox.set_motor(control['joint'], -control['speed'], max_torque=control['torque'])
